<?php $cls = static fn (string $k) => 'fld' . (isset($errors[$k]) ? ' is-err' : ''); ?>
<form method="post" action="<?= e(url($editing ? 'admin/jadwal/' . $editing['id'] . '/ubah' : 'admin/jadwal/baru')) ?>" class="card narrow" novalidate data-loading="<?= e(t('Menyimpan…')) ?>">
  <?= csrf_field() ?><input type="hidden" name="class_id" value="<?= (int) $class['id'] ?>">
  <div class="card-h"><h3><?= e($editing ? t('Ubah jadwal') : t('Tambah jadwal')) ?> · <?= e($class['name']) ?></h3><span class="sub"><?= e(t('Semester :s', ['s' => $activeSemester['name'] ?? '—'])) ?></span></div>
  <?php if (!$periods): ?><div class="banner warn"><?= icon('alert') ?><div class="grow"><?= e(t('Jam pelajaran belum diatur.')) ?></div><a class="btn btn-outline sm" href="<?= e(url('admin/master/jam')) ?>"><?= e(t('Atur jam')) ?></a></div><?php endif; ?>
  <div class="g-form two">
    <div class="<?= $cls('day_of_week') ?>"><label for="day_of_week"><?= e(t('Hari')) ?></label><select class="inp" id="day_of_week" name="day_of_week"><?php foreach ($days as $dd): ?><option value="<?= $dd ?>"<?= selected($d['day_of_week'], $dd) ?>><?= e(day_name($dd)) ?></option><?php endforeach; ?></select><?= field_error($errors, 'day_of_week') ?></div>
    <div class="<?= $cls('subject_id') ?>"><label for="subject_id"><?= e(t('Mata pelajaran')) ?></label><select class="inp" id="subject_id" name="subject_id"><option value=""><?= e(t('— Pilih —')) ?></option><?php foreach ($subjects as $s): ?><option value="<?= (int) $s['id'] ?>"<?= selected($d['subject_id'], $s['id']) ?>><?= e($s['code'] . ' · ' . $s['name']) ?></option><?php endforeach; ?></select><?= field_error($errors, 'subject_id') ?></div>
  </div>
  <div class="g-form two">
    <div class="<?= $cls('period_start') ?>"><label for="period_start"><?= e(t('Jam mulai')) ?></label><select class="inp" id="period_start" name="period_start"><?php foreach ($periods as $n => $p): ?><option value="<?= (int) $n ?>"<?= selected($d['period_start'], $n) ?>><?= e(t('Jam ke-:n (:t)', ['n' => $n, 't' => substr($p['start_time'], 0, 5)])) ?></option><?php endforeach; ?></select><?= field_error($errors, 'period_start') ?></div>
    <div class="<?= $cls('period_end') ?>"><label for="period_end"><?= e(t('Jam selesai')) ?></label><select class="inp" id="period_end" name="period_end"><?php foreach ($periods as $n => $p): ?><option value="<?= (int) $n ?>"<?= selected($d['period_end'], $n) ?>><?= e(t('Jam ke-:n (:t)', ['n' => $n, 't' => substr($p['end_time'], 0, 5)])) ?></option><?php endforeach; ?></select><?= field_error($errors, 'period_end') ?></div>
  </div>
  <div class="<?= $cls('teacher_id') ?>"><label for="teacher_id"><?= e(t('Guru pengampu')) ?></label><select class="inp" id="teacher_id" name="teacher_id"><option value=""><?= e(t('— Belum ditentukan —')) ?></option><?php foreach ($teachers as $g): ?><option value="<?= (int) $g['id'] ?>"<?= selected($d['teacher_id'], $g['id']) ?>><?= e($g['name']) ?><?= $g['nip'] ? ' (' . e($g['nip']) . ')' : '' ?></option><?php endforeach; ?></select><p class="hint"><?= e(t('Guru pengampu otomatis bisa melihat kelas ini.')) ?></p><?= field_error($errors, 'teacher_id') ?></div>
  <div class="<?= $cls('room_id') ?>"><label for="room_id"><?= e(t('Ruangan')) ?></label><select class="inp" id="room_id" name="room_id"><option value=""><?= e(t('— Ikut ruangan kelas —')) ?></option><?php foreach ($rooms as $r): ?><option value="<?= (int) $r['id'] ?>"<?= selected($d['room_id'], $r['id']) ?>><?= e($r['code'] . ' · ' . $r['name']) ?></option><?php endforeach; ?></select><?= field_error($errors, 'room_id') ?></div>
  <div class="acts">
    <?php if ($editing): ?><?= post_button('admin/jadwal/' . $editing['id'] . '/hapus', 'Hapus', [], 'btn btn-ghost', 'Hapus jadwal ini?', 'trash') ?><?php endif; ?>
    <a class="btn btn-ghost" href="<?= e(url($back)) ?>"><?= e(t('Batal')) ?></a><button type="submit" class="btn btn-primary"><?= e($editing ? t('Simpan perubahan') : t('Tambah jadwal')) ?></button></div>
</form>
